#!/usr/bin/env python3
"""Editable Paper construction input. Not a browser renderer or product code."""
import json
from pathlib import Path
from html import escape

OUT=Path(__file__).parent/'foundation-inputs'
OUT.mkdir(parents=True,exist_ok=True)
D={'bg':'var(--noir-canvas)','panel':'var(--noir-panel)','raised':'var(--noir-raised)','selected':'var(--noir-selected)','ink':'var(--noir-text-primary)','secondary':'var(--noir-text-secondary)','muted':'var(--noir-text-tertiary)','accent':'var(--noir-champagne)','line':'#343434','up':'#b0d4b9','down':'#efa6ad','warn':'#e9be6a','focus':'#c4d9f4'}
L={'bg':'#f6f6f3','panel':'#ffffff','raised':'#f0f0ed','selected':'#e2e2dc','ink':'#1a1c20','secondary':'#51555b','muted':'#5f6368','accent':'#66543b','line':'#cbccc7','up':'#256341','down':'#a62d43','warn':'#82550d','focus':'#245c91'}
def text(s,size=14,color=None,weight=400,width=None,line=None):
    return f'<div style="font-family:Inter;font-size:{size}px;font-weight:{weight};line-height:{line or round(size*1.5)}px;color:{color or D["ink"]};'+(f'width:{width}px;flex-shrink:0;' if width else '')+'">'+escape(s)+'</div>'
def frame(s,style='',name=''):
    return '<div '+(f'layer-name="{escape(name)}" ' if name else '')+'style="display:flex;'+style+'">'+s+'</div>'
def col(s,style='',name=''):return frame(s,'flex-direction:column;'+style,name)
def row(s,style='',name=''):return frame(s,'flex-direction:row;'+style,name)
def btn(s,focus=False,p=D,selected=False):
    return col(text(s,13,p['ink'],600),'justify-content:center;align-items:center;height:44px;padding:0px 16px;border:1px solid '+('#6f6f6f' if p==D else '#85877f')+';border-radius:6px;'+(f'background-color:{p["selected"]};' if selected else '')+(f'outline:2px solid {p["focus"]};outline-offset:3px;' if focus else ''),s)
def title(k,h,sub):
    return col(text(k,12,D['accent'],600)+text(h,32,D['ink'],600,line=40)+text(sub,15,D['secondary'],width=1240),'gap:12px;width:1344px;',h)
def note(h,s,p=D):
    return col(text(h,14,p['ink'],600)+text(s,13,p['secondary'],width=1296),'gap:8px;padding:20px 24px;background-color:'+p['panel']+';width:1344px;',h)
def step(k,h,parent='board'):return {'key':k,'parent':parent,'html':h}
def board(k,name,page,steps,h=900):return {'key':k,'name':'F02 · '+name+' · Candidate 2','pageId':page,'width':1440,'height':h,'theme':'dark','styles':{'padding':'48px','gap':'24px','backgroundColor':D['bg'],'fontFamily':'Inter','color':D['ink'],'display':'flex','flexDirection':'column'},'steps':steps}
boards=[]

readme=[step('ownership',row(col(text('F02-SYSTEM / 1.0.0-candidate.2',16,weight=600)+text('Shared anatomy, tokens, charts, tables, evidence and recovery.',15,D['secondary'],width=640),'gap:8px;width:656px;')+col(text('Draft for independent review',16,weight=600)+text('Native editable construction. Production behavior remains unverified.',15,D['secondary'],width=640),'gap:8px;width:656px;'),'gap:32px;padding:24px 0px;border-top:1px solid #343434;border-bottom:1px solid #343434;')),
step('journey',col(text('THE USER JOURNEY',12,D['muted'],600)+text('Question & period  →  comparison  →  limitations  →  exact evidence  →  return  →  owner-confirmed action',21,weight=500,width=1310,line=32),'gap:12px;')),
step('scope',row(col(text('Own the shared behavior',20,weight=600)+text('Read a dense comparison in light or dark. Distinguish direction from workflow status, unknown from zero, stale from partial, and selection from focus. Open the exact row and return without losing context.',15,D['secondary'],width=640,line=24),'gap:12px;width:656px;')+col(text('Preserve domain meaning',20,weight=600)+text('F01 owns navigation and shell composition. D07 owns Company statement modes; D08 owns the Options workflow; D23/current service owns save confirmation. Verdicts, count partitions and lifecycle transitions retain their domain owners.',15,D['secondary'],width=640,line=24),'gap:12px;width:656px;'),'gap:32px;')),
step('limitations',note('Current qualification','Direct Paper construction is qualified. F01 joint shell release, admitted independent review, real keyboard/touch/400% browser behavior and consumer integration remain separate gates. Every new numerical example is an illustrative fixture. No product code, merge or deployment is implied.')),
step('source',col(text('BUILD FROM THE SOURCE CONTRACT',12,D['muted'],600)+text('github.com/mastermindx-market-intelligence/macro/pull/10630',15,D['accent'])+text('Reviewed source: d68d5ecfbcd7e29094f59af3f44e7ae2a0f7f940',13,D['secondary'])+text('research/design_candidates/production_design_20261102/f02/',13,D['secondary'])+text('SYSTEM_CONTRACT.md · SOURCE_AND_DATA_CONTRACT.md · INTERACTION_STATES.md · VERIFICATION.md',14,D['ink'],500)+text('Capability ledger: 36 retained/improved capabilities. Paper ledger: 67 originals retained at their existing locations.',14,D['secondary']),'gap:10px;')),
step('construction',note('How to use this file','Start with Foundations, then Metrics & receipts, Controls & evidence, States, and Table/chart grammar. Compare Macro, Company, Options and editorial reference boards. Mobile boards define narrow hierarchy and evidence overlays. Utilities contain builder acceptance and source ownership. Candidate boards are prefixed F02; retained originals remain evidence.'))]
boards.append(board('readme','Read me & Build contract','p-2-0',readme))

found=[step('title',title('F02-P02 / FOUNDATIONS','One system. Clear semantic boundaries.','Neutral surfaces organize the workspace. Color reinforces an explicit label or mark; it never carries meaning alone.'))]
semantic=[('Canvas / surface / raised','bg','panel','raised'),('Primary / secondary / metadata','ink','secondary','muted'),('Selected / focus / attention','selected','focus','accent'),('Increase / decrease / caution','up','down','warn')]
for n,(label,*roles) in enumerate(semantic):
    samples=''
    for p,theme in [(D,'DARK / NOIR'),(L,'LIGHT / READING')]:
        chips=''
        for role in roles:
            swatch=col('',f'width:36px;height:36px;background-color:{p[role]};border:1px solid {p["line"]};border-radius:4px;')
            chips+=row(swatch+col(text(role,13,p['ink'],600)+text(p[role].replace('var(','').replace(')',''),11,p['secondary']), 'gap:2px;'),'gap:10px;align-items:center;width:200px;')
        samples+=col(text(theme+' · '+label,12,p['muted'],600)+row(chips,'gap:12px;'),'gap:16px;padding:20px;width:656px;background-color:'+p['bg']+';')
    found.append(step('semantic-'+str(n),row(samples,'gap:32px;')))
found += [step('type',row(col(text('TYPOGRAPHY',12,D['muted'],600)+text('32 / Clear question',32,weight=600,line=40)+text('20 / Section title',20,weight=600)+text('16 / Comfortable reading',16)+text('13 / Dense analytical row',13)+text('12 / Source, unit and status',12,D['secondary']),'gap:12px;width:656px;')+col(text('DENSITY & NUMBER ANATOMY',12,D['muted'],600)+text('Dense 40px · Comfortable 52px · Phone rows ≥48px',17,weight=500)+text('Important phone controls: 44 × 44px',16)+text('66.70%    +1.13 pp    0.00 USD/share    — Unknown',17,weight=500)+text('Inter tabular numerals; decimal alignment. Unit and comparison period travel with the value. Percent, percentage points and basis points are different quantities.',14,D['secondary'],width=640,line=22),'gap:16px;width:656px;'),'gap:32px;padding:24px 0px;')),
step('icons',row(col(text('ICON & FOCUS ANATOMY',12,D['muted'],600)+text('16 / 20px icon · consistent stroke · named control',16)+text('Focus has a 2px high-contrast outline with a 3px offset. Selected uses neutral fill plus weight. Focus is visible on an already selected item.',14,D['secondary'],width=840),'gap:12px;width:872px;')+btn('Selected tab',False,selected=True)+btn('Focused tab',True),'gap:24px;align-items:center;')),
step('mapping',note('Source mapping; no global replacement','Reuse the current --noir-* Paper tokens shown above. Light values and directional roles are candidate values from token-map.json, not a new global CSS namespace. Macro theme.css, Terminal globals/shared shell and public templates retain their separate owners. --sp-8 and radius-md have observed estate collisions. Read the migration contract before mapping aliases.'))]
boards.append(board('foundations','Semantic roles, type & density','p-3-0',found))

metrics=[step('title',title('F02-P03 / METRICS & RECEIPTS','The value is only half the fact.','Every observation keeps its entity, unit, period, comparator and source. Missing values never borrow the appearance of zero.'))]
items=[('Participation rate','66.70%','+1.13 pp','Prior settled session: 65.57%','up'),('Earnings per share','—','Unknown','Not available in this fixture','muted'),('Dividend per share','0.00 USD','No cash dividend','Actual reported zero; not missing','ink')]
cards=''
for a,b,c,d,colr in items:cards+=col(text(a,14,D['secondary'])+text(b,34,weight=600,line=42)+text(c,16,D[colr],500)+text(d,13,D['secondary']),'gap:12px;width:432px;padding:24px 0px;border-top:1px solid #343434;')
metrics.append(step('metric-trio',row(cards,'gap:24px;')))
metrics.append(step('metric-units',note('Comparator policy','65.57% → 66.70% is +1.13 percentage points. Relative change would be +1.72%, with a different label. Zero → zero dividend has an absolute change of 0.00 USD/share; percent change from zero is undefined. If the baseline is unknown, the delta is unavailable.')))
metrics.append(step('table-caption',row(text('Sector participation · illustrative settled observation',18,weight=600,width=1036)+text('Raw-value sort ↓',13,D['secondary']),'align-items:center;')))
widths=[344,180,180,180,270,140]
def data_row(values,selected=False,header=False):
    cells=''.join(col(text(v,12 if header else 14,D['secondary'] if header else D['ink'],600 if header or selected else 400),'width:'+str(w)+'px;flex-shrink:0;justify-content:center;'+('align-items:flex-end;padding-right:24px;' if i in [1,2,3] else '')) for i,(v,w) in enumerate(zip(values,widths)))
    return row(cells,'width:1344px;min-height:'+('36' if header else '48')+'px;padding:0px 12px;box-sizing:border-box;background-color:'+(D['selected'] if selected else D['bg'])+';border-bottom:1px solid #343434;')
metrics.append(step('row-header',data_row(['Sector','Above 50d MA','Change','Coverage','Source observation','Evidence'],header=True)))
for i,v in enumerate([['Information technology','74.20%','+2.10 pp','178 / 184','30 Oct · 20:00 UTC','Inspect row'],['Utilities','52.80%','−0.40 pp','63 / 63','30 Oct · 20:00 UTC','Inspect row'],['Energy','—','Unavailable','0 / 82','No observation','Coverage reason']]):metrics.append(step('data-'+str(i),data_row(v,selected=i==0)))
metrics.append(step('source-receipt',col(text('EVIDENCE / INFORMATION TECHNOLOGY / PARTICIPATION',12,D['muted'],600)+text('74.20% above 50-day moving average',24,weight=600)+row(col(text('Observed',12,D['muted'],600)+text('30 Oct 2026 · 20:00 UTC',15),'gap:8px;width:416px;')+col(text('Published',12,D['muted'],600)+text('30 Oct 2026 · 20:02 UTC',15),'gap:8px;width:416px;')+col(text('Retrieved',12,D['muted'],600)+text('30 Oct 2026 · 20:03 UTC',15),'gap:8px;width:416px;'),'gap:24px;')+text('178 / 184 securities · partial coverage · illustrative fixture · connected transport is independent of source freshness.',14,D['secondary']),'gap:18px;padding:24px;background-color:var(--noir-panel);width:1344px;')))
metrics.append(step('row-behavior',note('Evidence and table contract','The evidence trigger uses stable entity + field + observation identity. The accessible name includes the sector. Raw numbers determine sort order; unknowns sort last. Selection is neutral fill plus weight, not a colored edge. Keep numeric lanes and source context when density changes.')))
boards.append(board('metrics','Metric, change & source receipt','p-4-0',metrics))

controls=[step('title',title('F02-P04 / CONTROL & EVIDENCE ANATOMY','A predictable return to the question.','Selection, keyboard focus, access and save outcome are independent. Navigation or preference changes never silently save.')),
step('tabs',row(col(text('MANUAL-ACTIVATION TABS',12,D['muted'],600)+text('Arrows / Home / End move focus. Enter / Space activates.',15,D['secondary']),'gap:10px;width:680px;')+btn('Overview')+btn('Table',True)+btn('Sources'),'gap:16px;align-items:center;')),
step('actions',row(col(text('ACTION HIERARCHY',12,D['muted'],600)+text('Confirm the domain action; keep its real owner and result.',15,D['secondary']),'gap:10px;width:680px;')+btn('Save view')+btn('Source details')+btn('More'),'gap:16px;align-items:center;')),
step('evidence-shell',row(col(text('Primary table remains readable',24,weight=600)+text('At 1440px: content 1168px. Inspector 320px + gap 24px leaves 824px for the analytical region.',16,D['secondary'],width=840)+text('Dock only when at least 640px remains for the primary task. Otherwise use a modal overlay. F01 owns the final shell release.',14,D['secondary'],width=840)+text('The dock does not trap focus. Escape closes it and returns to the current row trigger. If that row disappeared, focus the named table fallback.',14,D['secondary'],width=840),'gap:20px;width:872px;padding:24px;background-color:var(--noir-panel);')+col(text('Evidence',22,weight=600)+text('Information technology',15,weight=600)+text('Participation · 30 Oct 2026',13,D['secondary'])+text('74.20%',36,weight=600)+text('178 / 184 covered',14)+text('Partial coverage',14,D['warn'],600)+text('Missing securities are not counted as below-average observations.',13,D['secondary'],width=272)+btn('Close evidence'),'gap:14px;width:320px;padding:24px;background-color:var(--noir-raised);'),'gap:24px;')),
step('disclosure',col(row(text('How participation is calculated',17,weight=600,width=1156)+text('Expanded −',14,D['secondary']),'align-items:center;')+text('Numerator: covered securities whose close is above their 50-day moving average. Denominator: covered securities with both valid observations. Coverage is shown separately from the statistic.',15,D['secondary'],width=1288,line=24),'gap:16px;padding:24px 0px;border-top:1px solid #343434;border-bottom:1px solid #343434;')),
step('keyboard',note('Keyboard, touch and route continuity','Modal: named dialog, initial focus, focus trap, Escape and close return. Dock: no trap. Preserve the existing URL-addressable tab, sort/filter state and scroll on return. Important phone actions are 44px. A 400% zoom view requires actual browser verification; Paper drawings specify expected reflow only.')),
step('saves',note('Save belongs to D23 / the existing service','Idle → pending → saved only after owner confirmation/readback. Pending disables duplicate send. Failure retains the draft for recovery. An expired session after dispatch produces uncertain outcome and reconciliation, not “nothing was sent.” Theme, locale, region and navigation changes do not save.'))]
boards.append(board('controls','Tabs, actions & evidence inspector','p-4-0',controls))

grammar=[step('title',title('F02-P06 / TABLE & CHART GRAMMAR','Comparison first. Exact values always reachable.','Charts explain shape. Tables preserve the actual observations, units and exceptions. Neither may silently fill a gap.')),
step('chart-title',row(text('Participation across eight settled sessions',20,weight=600,width=1016)+text('Unit: percent · linear 50–80% scale',13,D['secondary']),'align-items:center;'))]
vals=[61.2,63.4,62.1,None,65.57,64.9,65.57,66.7]; ys=[204-(v-50)*5 if v is not None else None for v in vals];xs=[80+i*168 for i in range(8)]
lines=''.join(f'<line x1="80" y1="{204-(v-50)*5}" x2="1256" y2="{204-(v-50)*5}" stroke="#343434" />' for v in [50,60,70,80])
for i in range(7):
    if ys[i] is not None and ys[i+1] is not None:lines+=f'<line x1="{xs[i]}" y1="{ys[i]}" x2="{xs[i+1]}" y2="{ys[i+1]}" stroke="#c9b99b" stroke-width="3" />'
lines+=''.join(f'<circle cx="{x}" cy="{y}" r="5" fill="#c9b99b" />' for x,y in zip(xs,ys) if y is not None)
chart='<svg width="1296" height="230" viewBox="0 0 1296 230" xmlns="http://www.w3.org/2000/svg">'+lines+'</svg>'
# Native text is centered on the matching SVG gridline. The 24px root padding
# offsets the original plot; absolute labels do not change its geometry or flow.
axis_labels=''.join(frame(text(f'{v}%',12,D['secondary'],line=18),f'position:absolute;left:24px;top:{24+204-(v-50)*5-9}px;width:64px;height:18px;justify-content:flex-end;align-items:center;',f'Y axis / {v}%') for v in [50,60,70,80])
# Match the verified native correction: center each 100px date label on its
# existing point x coordinate, without moving the plot or its data marks.
date_labels=''.join(text(d,12,D['secondary'],width=100).replace('style="',f'style="position:absolute;left:{80+i*168-50}px;top:0px;text-align:center;',1) for i,d in enumerate(['21 Oct','22 Oct','23 Oct','26 Oct · —','27 Oct','28 Oct','29 Oct','30 Oct']))
grammar.append(step('chart',col(chart+axis_labels+row(date_labels,'position:relative;width:1296px;height:18px;padding-left:0px;')+text('The line breaks at 26 Oct. No interpolation, zero substitution or implied observation.',14,D['secondary']),'position:relative;gap:12px;padding:24px;background-color:var(--noir-panel);')))
grammar.append(step('exact-values',row(''.join(col(text(d,12,D['secondary'])+text('—' if v is None else f'{v:.2f}%',16,weight=600),'gap:8px;width:168px;') for d,v in zip(['21 Oct','22 Oct','23 Oct','26 Oct','27 Oct','28 Oct','29 Oct','30 Oct'],vals)),'width:1344px;padding:12px 0px;')))
grammar += [step('chart-source',note('Source and exact-value access','Illustrative fixture, settled sessions, percent. In implementation every point has keyboard/touch access to the same exact-value receipt; the table provides an equivalent path. A timestamped source clock and coverage label accompany the figure. The incumbent lib/illus.py cleaner drops nulls: a gap-rendering change needs the later domain implementation and proof.')),
step('comparison-rules',row(col(text('TABLE',12,D['accent'],600)+text('Caption, scoped column headers and stable row identity.',17,weight=500)+text('Right-align numeric values; preserve native precision in export. Raw values sort, missing values last. Truncation never hides the only route to full identity. Keep controls in fixed lanes.',15,D['secondary'],width=640,line=24),'gap:14px;width:656px;')+col(text('CHART',12,D['accent'],600)+text('Declare unit, scale, period and missing-data behavior.',17,weight=500)+text('No decorative smoothing. Series have labels and distinguishable marks. Use 12px minimum axis labels in dense analytics. Long Company histories scroll inside a named frame, with all 17 × 5 raw observations available.',15,D['secondary'],width=640,line=24),'gap:14px;width:656px;'),'gap:32px;')),
step('virtualization',note('Virtualized and narrow data','Retain the real DataInspector 50,000-row cap, time keys and keyboard behavior. Virtualization is a performance implementation detail, not permission to omit rows from accessible navigation or export. Keep horizontal movement local to the table/chart; full-row evidence gives a readable narrow path.'))]
boards.append(board('grammar','Table and chart grammar','p-5-0',grammar))

builder=[step('title',title('F02-P12 / BUILD CONTRACT','Integrate through the existing owners.','This kit specifies shared anatomy and behavior. It preserves source contracts, domain semantics and existing capabilities.'))]
mapping=[('Macro','theme.css · actual current chart/table builders','Source observation + coverage; no null-to-zero or interpolation.'),('Company / D07','CompanyAnalysisWorkspace · getFund / getBars / intel / quote','Entity/listing identity, request-race guards, annual/quarterly and statement currency.'),('Options / D08','meta.observed_statistics · options.observed_statistics_snapshot/v1','Print window ≠ expiry buckets. Side evidence ≠ workflow health. Transport ≠ freshness.'),('Public editorial','seo_article / seo_base','English article body, bilingual chrome, canonical anchors and existing routes.'),('Save / D23','Existing mutation service and owner-confirmed readback','Pending deduplication, recoverable failure and reconciliation for uncertain outcome.'),('Domain patterns','Retained verdict / decision / count / lifecycle boards','Shared anatomy must not redefine verdict authority, count partitions or transitions.')]
for i,(a,b,c) in enumerate(mapping):builder.append(step('owner-'+str(i),row(text(a,15,weight=600,width=210)+col(text(b,15,weight=500)+text(c,14,D['secondary'],width=1080),'gap:8px;width:1110px;'),'gap:24px;padding:18px 0px;border-bottom:1px solid #343434;')))
builder += [step('widths',note('Responsive acceptance matrix','320/390: compact header, one vertical hierarchy, 44px actions and modal evidence. 768/1024: avoid shrinking dense data below its meaningful minimum; use local scroll. 1280/1440/1600: dock only with ≥640px primary region. Baseline rail224/header64/mainpad24 remains provisional until F01 joint release.')),
step('acceptance',note('Required real-path acceptance','Normal, unknown, zero, loading, empty, partial + stale, error, denied/expired access and pending/failed/uncertain save. Light/dark; EN/ZH chrome; keyboard, touch, focus return, URL/history, 400% reflow. Test representative actual consumers before adoption. Static design and Paper readback do not establish runtime behavior.')),
step('performance',note('Targets and migration','Future p75 targets: LCP ≤2.5s, INP ≤200ms, CLS ≤0.1; no current measurements asserted. Migrate one consumer slice behind its existing owner, preserve routes/auth/data shape, compare before/after, then expand. Roll back by restoring the prior component/template mapping, not by deleting retained evidence.')),
step('review',note('Review and continuity','Native Paper construction is a candidate for independent product and visual critique. Existing first-pass reports and repaired static artifact sets remain immutable. PRC-007 consumer-integration qualification remains open. Sector, Prophet and Refraction holds/conditions retain their original authority; this file creates no RIG approval.')),
step('refs',col(text('SOURCE PACKAGE / DRAFT #10630',12,D['muted'],600)+text('SYSTEM_CONTRACT.md · SOURCE_AND_DATA_CONTRACT.md §11 · INTERACTION_STATES.md',14,D['ink'])+text('CAPABILITY_LEDGER.md · PAPER_RETENTION_LEDGER.md · CONTINUITY_AND_GATES.md · VERIFICATION.md',14,D['ink'])+text('Reviewed source artifact: d68d5ecfbcd7e29094f59af3f44e7ae2a0f7f940',13,D['secondary'])+text('No global CSS fork. Consumers request versioned contract changes and affected review before adoption.',15,D['accent']),'gap:12px;'))]
boards.append(board('builder','Builder acceptance & source ownership','p-7-0',builder))
(OUT/'boards.json').write_text(json.dumps({'schema':'f02.paper.native-inputs.v1','boards':boards},indent=2,ensure_ascii=False))
print(json.dumps({'boards':len(boards),'steps':sum(len(b['steps']) for b in boards),'output':str(OUT/'boards.json')}))
